<template>
  <form @submit.prevent="submit()">
    <b-overlay :show="isLoading" rounded="sm">
      <div class="login-page">
        <div class="card">
          <div class="card-header">
            <h5 class="text-secondary text-center">Autenticação</h5>
          </div>
          <div class="card-body">
            <div class="form-group">
              <input
                required
                type="email"
                class="form-control"
                placeholder="E-mail ou telemóvel"
                v-model="form.email"
              />
            </div>
            <div class="form-group mt-2">
              <input
                required
                type="password"
                class="form-control"
                placeholder="Senha"
                v-model="form.password"
              />
            </div>
            <button class="btn btn-primary mt-2 w-100" :disabled="isLoading">
              Entrar
            </button>
          </div>
        </div>
      </div>
    </b-overlay>
  </form>
</template>

<script>
import { mapGetters } from "vuex";
import logs from "@/utils/logs";

export default {
  data: () => ({
    form: {
      email: "",
      password: "",
    },
  }),

  computed: {
    ...mapGetters(["isLoading", "user", "isLoggedIn", "success"]),
  },

  watch: {
    user: function () {
      setTimeout(() => {
        if (this.user.userRole === 1) {
          this.$router.replace("/dashboard");
        } else if (this.user.userRole === 0) {
          this.$store.commit("SET_PASSWORD_STATUS", this.user.updatedPassword);
          this.$router.replace("/company");
        }
      }, 1500);
    },
  },

  created() {
    if (this.user.userRole === 1) {
      this.$router.replace("/dashboard");
    } else if (this.user.userRole === 0) {
      this.$router.replace("/company");
    }
  },

  methods: {
    submit() {
      this.$store
        .dispatch("actionDoLogin", this.form)
        .then(() => {
          const logsParams = logs(
            this.user,
            `${this.form.email} - ${this.user.name} autenticado com sucesso.`,
            "Autenticação"
          );
          this.$store.dispatch("addLog", logsParams);
          this.showToast("", "success", this.success);
        })
        .catch(() => {
          this.showToast("Erro!", "danger", this.success);
        });
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 2000,
      });
    },
  },
};
</script>
<style scoped>
.login-page {
  height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
}

.card {
  width: 30%;
}
</style>
